import { FaScroll } from "react-icons/fa";
import { FaTimes } from "react-icons/fa";
import SpinnerIcon from "../SpinnerIcon";
import React, { useContext, useEffect, useMemo, useState } from "react";
import { useLocation, useNavigate, useParams } from "react-router-dom";
import { FaBook } from "react-icons/fa";

import { FaBars } from "react-icons/fa";
import { store } from "../../NewContext";
import { existsSync } from "../../storage";
import { loadFile } from "../../utils/";
import { loadTabs, saveTabs } from "../../tabs";
import {GiSpiderWeb, GiSewingString, GiLightBulb} from "react-icons/gi";
import { HiPuzzle } from "react-icons/hi";
import { analysisById } from "../Analysis";
import { mapById } from "../../maps";
import { timelineById } from "../../timelines";
import { FaMapMarkedAlt, FaStream, FaSlidersH, FaInfoCircle } from "react-icons/fa";
import "./TabBar.css";

const TYPE_ICON = {
  element: <HiPuzzle />,
  fact: <GiLightBulb />,
  snippet: <FaScroll />,
  thread: <GiSewingString />,
  web: <GiSpiderWeb />,
};

/**
 * Editor tabs across the top of the workspace. Opening an actor adds a tab;
 * tabs survive reloads per project. Middle-click or × closes.
 */
const TabBar = ({ onMenu }) => {
  const { state } = useContext(store);
  const params = useParams();
  const pathname = useLocation().pathname;
  const isWiki = pathname.startsWith("/wiki");
  const isSpinner = pathname.startsWith("/spinner");
  const isPrefs = pathname.startsWith("/preferences");
  const isAbout = pathname.startsWith("/about");
  // a tab key is an actor file, "analysis:<id>", "wiki" or "spinner"
  const file = isAbout ? "about" : isPrefs ? "preferences" : isSpinner ? "spinner" : isWiki ? "wiki" : params.mapId ? "map:" + params.mapId : params.tlId ? "timeline:" + params.tlId : params.id ? "analysis:" + params.id : params.file;
  const navigate = useNavigate();
  const project = state.project;
  const [tabs, setTabs] = useState(() => loadTabs(project));

  // Reload the set when the project changes, or when something else (Spinner) edits the tabs.
  useEffect(() => {
    setTabs(loadTabs(project));
    const on = () => setTabs(loadTabs(project));
    window.addEventListener("silky-tabs", on);
    return () => window.removeEventListener("silky-tabs", on);
  }, [project]);

  // The routed file is always an open tab; a routed file that has gone to
  // the rubbish closes its tab and moves to a neighbour.
  useEffect(() => {
    if (!file) return;
    if (!isLive(file)) {
      if (tabs.includes(file)) {
        const liveNow = tabs.filter(isLive);
        const i = tabs.indexOf(file);
        const neighbour = tabs.slice(i + 1).find((f) => liveNow.includes(f)) || [...tabs.slice(0, i)].reverse().find((f) => liveNow.includes(f));
        const next = tabs.filter((x) => x !== file);
        setTabs(next);
        saveTabs(project, next);
        navigate(neighbour ? hrefOf(neighbour) : "/elements/", { replace: true });
      }
      return;
    }
    if (tabs.includes(file)) return;
    const next = [...tabs, file];
    setTabs(next);
    saveTabs(project, next);
  }, [file, tabs, project, state.dir, navigate]);

  const isLive = (f) => (f === "wiki" || f === "spinner" || f === "preferences" || f === "about" ? true : f.startsWith("analysis:") ? !!analysisById(f.slice(9)) : f.startsWith("map:") ? !!mapById(state.dir, f.slice(4)) : f.startsWith("timeline:") ? !!timelineById(state.dir, f.slice(9)) : existsSync(state.dir + f));
  const hrefOf = (f) => (f === "about" ? "/about" : f === "preferences" ? "/preferences" : f === "spinner" ? "/spinner" : f === "wiki" ? "/wiki/home" : f.startsWith("analysis:") ? "/analysis/" + f.slice(9) : f.startsWith("map:") ? "/map/" + f.slice(4) : f.startsWith("timeline:") ? "/timeline/" + f.slice(9) : "/elements/" + f);
  const live = useMemo(
    () => tabs.filter(isLive),
    // eslint-disable-next-line react-hooks/exhaustive-deps
    [tabs, state.dir, file]
  );

  const close = (f, e) => {
    if (e) {
      e.preventDefault();
      e.stopPropagation();
    }
    const i = live.indexOf(f);
    const next = tabs.filter((x) => x !== f);
    setTabs(next);
    saveTabs(project, next);
    if (f === file) {
      const neighbour = live[i + 1] || live[i - 1];
      navigate(neighbour ? hrefOf(neighbour) : "/elements/");
    }
  };

  const closeOthers = (keep) => {
    setTabs([keep]);
    saveTabs(project, [keep]);
    if (file !== keep) navigate(hrefOf(keep));
  };

  const menu = onMenu ? (
    <button type="button" className="tabBar__menu" aria-label="Open the list" onClick={onMenu}><FaBars /></button>
  ) : null;

  if (!live.length) return <div className={"tabBar" + (onMenu ? "" : " tabBar--empty")}>{menu}</div>;

  return (
    <div className="tabBar" role="tablist">
      {menu}
      {live.map((f) => {
        let a;
        if (f === "spinner") {
          a = { name: "Spinner", icon: <SpinnerIcon />, type: "analysis" };
        } else if (f === "preferences") {
          a = { name: "Preferences", icon: <FaSlidersH />, type: "analysis" };
        } else if (f === "about") {
          a = { name: "About", icon: <FaInfoCircle />, type: "analysis" };
        } else if (f === "wiki") {
          a = { name: "Wiki", icon: <FaBook />, type: "analysis" };
        } else if (f.startsWith("analysis:")) {
          const m = analysisById(f.slice(9));
          const Icon = m.icon;
          a = { name: m.name, icon: <Icon />, type: "analysis" };
        } else if (f.startsWith("map:")) {
          const m = mapById(state.dir, f.slice(4));
          a = m ? { name: m.name, icon: <FaMapMarkedAlt />, type: "analysis" } : null;
        } else if (f.startsWith("timeline:")) {
          const t = timelineById(state.dir, f.slice(9));
          a = t ? { name: t.name, icon: <FaStream />, type: "analysis" } : null;
        } else {
          a = loadFile(state.dir + f);
        }
        if (!a) return null;
        const active = f === file;
        return (
          <div
            key={f}
            role="tab"
            aria-selected={active}
            className={"tab" + (active ? " is-active" : "")}
            title={a.name}
            onClick={() => !active && navigate(hrefOf(f))}
            onAuxClick={(e) => e.button === 1 && close(f, e)}
            onDoubleClick={() => closeOthers(f)}
          >
            {a.type !== "analysis" && <span className="tab__type">{TYPE_ICON[a.type]}</span>}
            <span className="tab__icon">{a.icon}</span>
            <span className="tab__name">{a.name}</span>
            <button type="button" className="tab__close" aria-label={"Close " + a.name} onClick={(e) => close(f, e)}><FaTimes /></button>
          </div>
        );
      })}
    </div>
  );
};

export default TabBar;
